  "rung_purposes": [
    {
      "rung": 1,
      "purpose": "R1: Detect conveyor motor overload trip (X13 open) and set alarm M191."
    },
    {
      "rung": 2,
      "purpose": "R2: Reset ST10 fault latch M190 when reset pushbutton X1 is pressed."
    },
    {
      "rung": 3,
      "purpose": "R3: Evaluate common fault M199 from fault latch M190, motor overload M191, or E-stop loss."
    },
    {
      "rung": 4,
      "purpose": "R4: Energize conveyor motor contactor Y10 when auto mode is selected and no fault is active."
    },
    {
      "rung": 5,
      "purpose": "R5: Indicate pallet in position (M100) from pallet stop photo-eye X10."
    },
    {
      "rung": 6,
      "purpose": "R6: Latch stopper release solenoid Y11 on rising edge of line controller request X14."
    },
    {
      "rung": 7,
      "purpose": "R7: Run 2.0 s pulse timer T11 while stopper release solenoid Y11 is active."
    },
    {
      "rung": 8,
      "purpose": "R8: Unlatch stopper release solenoid Y11 once timer T11 completes."
    },
    {
      "rung": 9,
      "purpose": "R9: End of program scan."
    }
  ],
